49	     * BuiltInPartitioner constructor.
50	     *
51	     * @param topic The topic
52	     * @param stickyBatchSize How much to produce to partition before switch
53	     */
54	    public BuiltInPartitioner(LogContext logContext, String topic, int stickyBatchSize) {
55	        this.log = logContext.logger(BuiltInPartitioner.class);
56	        this.topic = topic;
57	        if (stickyBatchSize < 1) {
58	            throw new IllegalArgumentException("stickyBatchSize must be >= 1 but got " + stickyBatchSize);
59	        }
60	        this.stickyBatchSize = stickyBatchSize;
61	    }
