684	            final int dequeSize;
685	            final boolean full;
686	
687	            OptionalInt leaderEpoch = metadataSnapshot.leaderEpochFor(part);
688	
689	            // This loop is especially hot with large partition counts. So -
690	
691	            // 1. We should avoid code that increases synchronization between application thread calling
692	            // send(), and background thread running runOnce(), see https://issues.apache.org/jira/browse/KAFKA-16226
693	
694	            // 2. We are careful to only perform the minimum required inside the
